import { InvoiceRow } from '../../slots/defs/invoiceRow';

// An invoice's payment status cell — its own file filling the invoice.row region (CLAUDE.md rule 3).
// Reads the status from the row's context (the value the table already queried for) and renders it
// under data-testid="invoice-status" (the test contract).
export const contribution = InvoiceRow.fill({
  order: 10,
  Component: ({ status }: { invoiceId: number; projectId: number; status: string }) => (
    <td data-testid="invoice-status">{status}</td>
  ),
});
===== detail-status.slot.tsx =====
import { useQuery } from '@tanstack/react-query';
import { InvoiceDetail } from '../../slots/defs/invoiceDetail';
import { fetchInvoiceStatus, invoiceStatusKey } from './queries';

// The invoice's status on its detail page — its own file filling the InvoiceDetail region (CLAUDE.md
// rule 3); nothing existing is edited to add it. The status is DERIVED from the payments recorded
// (PAID / PARTIAL / SENT), so it is never flipped by hand. It queries for itself under the shared
// payments key, so recording a payment (which invalidates ['payments', invoiceId]) refreshes it
// (rule 5). Renders under data-testid="invoice-status" (the test contract).
function InvoiceStatusPanel({ invoiceId }: { invoiceId: number }) {
  const { data } = useQuery({
    queryKey: invoiceStatusKey(invoiceId),
    queryFn: () => fetchInvoiceStatus(invoiceId),
  });

  if (!data) {
    return null;
  }

  return <p data-testid="invoice-status">{data.status}</p>;
}

export const contribution = InvoiceDetail.fill({ order: 5, Component: InvoiceStatusPanel });
===== due-amount.slot.tsx =====
import { useQuery } from '@tanstack/react-query';
import { InvoiceRow } from '../../slots/defs/invoiceRow';
import { invoicesKey, fetchInvoices, type Invoice } from './queries';
import { formatMoney } from '../../ui/money';

// The "still due after payments" cell on every invoice row — its own file filling the invoice.row
// region (CLAUDE.md rule 3). The amount due (invoice amount minus its payments) is derived
// server-side and carried on each invoice, so this cell reads the SAME ['invoices', projectId]
// query the table already loaded (rule 5) and finds its own invoice — no parent hands it the value,
// and a payment write that invalidates the key refreshes this cell for free. Renders under
// data-testid="invoice-due-amount" (the test contract).
export const contribution = InvoiceRow.fill({
  order: 15,
  Component: ({ invoiceId, projectId }: { invoiceId: number; projectId: number; status: string }) => {
    const { data: invoices } = useQuery({
      queryKey: invoicesKey(projectId),
      queryFn: () => fetchInvoices(projectId),
    });
    const invoice = invoices?.find((row: Invoice) => row.id === invoiceId);
    if (!invoice) {
      return null;
    }
    return <td data-testid="invoice-due-amount">{formatMoney(invoice.due)}</td>;
  },
});

